function loginOptions(context) {
  const CONTAINER_CLASS = 'af-accountLinkingOptions';

  const container = document.createElement('div');
  container.classList.add(CONTAINER_CLASS);

  const CONNECTION_MAPPING = {
    'google-oauth2': {
      text: 'Google',
    },
    'Username-Password-Authentication': {
      text: 'Email',
    },
  };

  function buildAuthorizeUrl(connection) {
    const config = context.custom.getParams();
    const { client_id, email, app_hostname } = config;

    const BASE_URL = `https://${app_hostname}`;
    const AUTHORIZE_PATH = '/authorize';

    const AUTHORIZE_URL = new URL(AUTHORIZE_PATH, BASE_URL);

    AUTHORIZE_URL.searchParams.append('client_id', client_id);
    AUTHORIZE_URL.searchParams.append('response_type', 'code');
    AUTHORIZE_URL.searchParams.append('prompt', 'login');
    AUTHORIZE_URL.searchParams.append('account_linking', 'true');
    AUTHORIZE_URL.searchParams.append('connection', connection);
    AUTHORIZE_URL.searchParams.append('login_hint', email);
    AUTHORIZE_URL.searchParams.append('scope', 'openid profile');
    AUTHORIZE_URL.searchParams.append('redirect_uri', window.location.href);

    return AUTHORIZE_URL.href;
  }

  function buildButton(href, connection) {
    const button = document.createElement('a');
    button.classList.add('af-button', 'af-nextButton', 'af-customButton');
    button.setAttribute('data-connection', connection);
    button.href = href;

    const logo = document.createElement('span');
    logo.classList.add('af-customButtonIcon');

    const text = document.createElement('span');
    text.innerText = `Continue with ${CONNECTION_MAPPING[connection]?.text ?? connection}`;

    button.appendChild(logo);
    button.appendChild(text);

    return button;
  }

  function buildLoginOptions() {
    const config = context.custom.getParams();
    const { candidate_identities } = config;

    candidate_identities.forEach((option) => {
      const href = buildAuthorizeUrl(option.connection);
      const button = buildButton(href, option.connection);

      container.appendChild(button);
    });
  }


  return {
    init() {
      buildLoginOptions();
      return container;
    },
  };
}

